window.kbPageData["views/practice/s-5cd530a611f08110"] = {"key":"practice/s-5cd530a611f08110","state":{"route":"practice/s-5cd530a611f08110"},"tree":"<a data-toc-link href=\"#skills/shenlun\">申论技能首页</a><details data-branch=\"module-归纳概括\"><summary>归纳概括</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c898afc5816920c2\">概括作用与成效</a><a data-toc-link href=\"#practice/s-0b47c7faa1dcfbc7\">提炼做法与经验</a><a data-toc-link href=\"#practice/s-75a1eb1e46268fd8\">归类概括材料中的问题</a><a data-toc-link href=\"#practice/s-4863baf2b4febcf4\">配对概括做法与成效</a><a data-toc-link href=\"#practice/s-c94c813ed743298a\">从材料提取概念特征</a><a data-toc-link href=\"#practice/s-4da331cba0998f2b\">分条梳理不同立场与分歧</a></div></details><details data-branch=\"module-综合分析\"><summary>综合分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-43e39afd29a17e74\">解释含义与作用</a><a data-toc-link href=\"#practice/s-599008555ed60dda\">分析现象形成的原因</a><a data-toc-link href=\"#practice/s-93367fee5c934df6\">从案例推导改进建议</a></div></details><details data-branch=\"module-提出对策\"><summary>提出对策</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c6bd983baf5dd3ae\">根据问题成因逐项提出措施</a><a data-toc-link href=\"#practice/s-ecba3f8c2c1d3b9b\">将外地经验转化为本地措施</a><a data-toc-link href=\"#practice/s-9b570af6b9f113ee\">按治理环节组织对策</a><a data-toc-link href=\"#practice/s-91888cb77ec12615\">从材料反馈中提炼改进建议</a></div></details><details data-branch=\"module-应用文写作\" open><summary>应用文写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-171ebed39b4fe1cf\">汇报与交流发言</a><a data-toc-link href=\"#practice/s-b92b682e65d12042\">面向公众动员参与</a><a data-toc-link href=\"#practice/s-cabc6af5d656b214\">宣传介绍与活动报道</a><a data-toc-link href=\"#practice/s-5cd530a611f08110\" aria-current=\"page\">编写案例摘要</a><a data-toc-link href=\"#practice/s-9f175b7eb1a79028\">陈述事由与请求</a><a data-toc-link href=\"#practice/s-38dece0b54a49be3\">拟定工作事项与措施</a><a data-toc-link href=\"#practice/s-c8dfde3ede3eadab\">撰写案例短评或点评</a></div></details><details data-branch=\"module-文章写作\"><summary>文章写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-b8139af04b609dce\">展开分论点的论证</a><a data-toc-link href=\"#practice/s-4fdadcb77809c673\">围绕中心论点组织分论点</a><a data-toc-link href=\"#practice/s-ab43045e4cab9ffe\">从材料立意并确立中心论点</a></div></details>","packs":{"国考 2023 地市级 申论#2":"55950c2014fcb5adc2d61aa2","国考 2023 行政执法 申论#4":"55950c2014fcb5adc2d61aa2"},"questions":{"国考 2023 地市级 申论#2":{"paper":"国考 2023 地市级 申论","n":2,"mod":"申论","src":["ac29447768aa30db2247.pdf",4],"asrc":["88c33effee950c9e9e6a.pdf",1]},"国考 2023 行政执法 申论#4":{"paper":"国考 2023 行政执法 申论","n":4,"mod":"申论","src":["6d1ab3337cf152c6c10f.pdf",4],"asrc":["c433c5baa0d4806d0f4a.pdf",3]}},"first":{"qs":{"国考 2023 地市级 申论#2":{"paper":"国考 2023 地市级 申论","n":2,"mod":"申论","src":["ac29447768aa30db2247.pdf",4],"asrc":["88c33effee950c9e9e6a.pdf",1],"m":["dd9e2108e0e953e8"],"task":"根据给定资料2，在300字内为《知识产权服务案例汇编》撰写L市知识产权信息服务中心的案例摘要，简述中心背景，分案例概括主要做法及成效。","current_affairs":{"state":"否","event":null,"year":null,"basis":"完成摘要所需的服务做法及成效均由材料给出。"},"links":[{"id":"k-aafae58dc3dcc99d","label":"地理标志保护带动地方特色产品品牌和行业发展","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"‘川兴米粉’获得地理标志保护，带动了整个企业品牌乃至行业的发展。","why":"概括川兴米粉案例需要交代地理标志保护及其对品牌和行业的带动作用。","origin":"逐题标记"},{"id":"k-da7b6ec6c3500908","label":"制定联盟标准和地方标准推动特色产品提质与规范化","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"引导出台联盟及地方标准，提升\n产品质量，实现标准化、规范化的高质量发展。","why":"标准制定及其质量成效构成川兴米粉案例的另一项要点。","origin":"逐题标记"},{"id":"k-d46e483cd5c929cb","label":"按企业生产难题对接科研团队并引进适用技术","catalog_id":null,"type":"方法与技能","role":"直接考查","field":"answer","quote":"协调引进先进种植技术，方便采收、有效增产。","why":"参考答案将研判问题、促成科研合作和引进技术概括为解决生产难题的做法，以省力增产体现成效。","origin":"逐题标记"},{"id":"k-4859f93707a81f3e","label":"通过商标注册、授权和规范使用提升区域品牌信誉","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"现在我们得到商标的授权，消费者对我们的信任度高了","why":"伊山山珍案例以注册方案、宣讲培训和标识使用管理为做法，以消费者信任提升为成效。","origin":"逐题标记"},{"id":"k-58f1053a07e73a56","label":"多部门协同以企业、地理标志商标、标准化和农户联动推广主导产业","catalog_id":null,"type":"方法与技能","role":"直接考查","field":"M1","quote":"联合多个部门合力推动“企业+地理标志商标+标准化+农户”模式","why":"参考答案将这一协同模式及其对主导产业推广和拳头产品市场认可度的作用列为案例要点。","origin":"逐题标记"},{"id":"s-5cd530a611f08110","label":"按案例归并并配对关键做法与成效","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"紧扣资料，内容全面，突出做法和意义","why":"以三个服务对象为单位归并分散信息，为各项关键做法匹配对应成效，并压缩为条理清晰的摘要。","origin":"逐题标记"}],"stem":"有关部门正在征集知识产权服务优秀案例，计划编印《知识产权服务案例汇编》。假如L市知识产权信息服务中心\n的相关实践入选为优秀案例，请你根据“给定资料2”，撰写一篇案例摘要。（15分）\n要求：\n（1）紧扣资料，内容全面，突出做法和意义；\n（2）表述准确，条理清晰；\n（3）不超过300字。","options":[],"answer":"","analysis":"关于L市知识产权信息服务中心案例摘要\n   该中心成立于2017年，持续面向社会开展知识产权服务工作，帮助一批品牌实现快速发展，典型案例有：\n   案例一——“川兴米粉”：指导其成为国家地理标志产品，带动品牌和行业发展；引导出台联盟及地方标准，提升\n产品质量，实现标准化、规范化的高质量发展。\n   案例二——“丰禾庄园”：协助企业分析研判发展问题，促成其与高端科研团队签署合作协议，解决生产中的关键\n问题，协调引进先进种植技术，方便采收、有效增产。\n   案例三——“伊山山珍”：定制品牌商标注册方案，开展宣讲培训，指导制定商标管理办法，提升信誉，联合多部\n门创新模式，推广主导产业，提升拳头产品市场认可度。\n   参考答案说明：（1）格式方面，本参考答案写到了“标题+正文”。（2）正文部分，一方面从内容上来看，围\n绕“L市知识产权信息服务中心的相关实践”这一主题，本参考答案的开头先写到了L市知识产权信息服务中心的背景信\n息；主体部分写到了“川兴米粉”“丰禾庄园”“伊山山珍”三个案例。另一方面，形式上，本参考答案做到了分段、分条\n撰写，整体上条理较为清晰。","figs":[],"state":"已标记","notes":[],"domains":["公共管理","经济"],"nature":"综合题","current":false},"国考 2023 行政执法 申论#4":{"paper":"国考 2023 行政执法 申论","n":4,"mod":"申论","src":["6d1ab3337cf152c6c10f.pdf",4],"asrc":["c433c5baa0d4806d0f4a.pdf",3],"m":["7c24d384bc901351"],"task":"根据给定资料4，在300字以内撰写L市知识产权信息服务中心的案例摘要，概括三个案例的主要做法及成效。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是给定材料中的地方服务实践及其成效，题目没有要求掌握窗口内发生的事件或政策部署。"},"links":[{"id":"k-aafae58dc3dcc99d","label":"地理标志保护带动地方特色产品品牌和行业发展","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"指导其成为国家地理标志产品，带动品牌和行业发展","why":"川兴米粉案例要求概括获得地理标志保护后的品牌和产业成效。","origin":"逐题标记"},{"id":"k-503f5332aa5742af","label":"以统一产品标准促进地方特色产品提质和规范化","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"提升产品质量，实现标准化、规范化的高质量发展","why":"川兴米粉案例要求交代引导出台联盟标准和地方标准的质量效益。","origin":"逐题标记"},{"id":"k-81247a9d1eef6b5e","label":"对接科研团队和引进适用技术可解决农业生产难题","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"问题，协调引进先进种植技术，方便采收、有效增产。","why":"丰禾庄园案例要求概括中心促成产学合作和引进高垄种植技术的成效。","origin":"逐题标记"},{"id":"k-c7b7c1663252e3e1","label":"商标注册服务和规范授权使用有助于维护区域品牌信誉","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"定制品牌商标注册方案，开展宣讲培训，指导制定商标管理办法，提升信誉","why":"伊山山珍案例要求交代注册指导、商标培训和使用管理对品牌信誉的作用。","origin":"逐题标记"},{"id":"k-1ba04b82345af203","label":"多部门协同运用地理标志商标和标准化推广地方主导产业","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"联合多个部门合力推动“企业+地理标志商标+标准化+农户”模式","why":"伊山山珍案例要求概括产业推广模式及其对重点产品市场认可度的作用。","origin":"逐题标记"},{"id":"s-5cd530a611f08110","label":"按案例提取并配对做法与成效","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"紧扣资料，内容全面，突出做法和意义","why":"需要从多段材料归并同一案例的信息，将主要服务举措与对应成效配对后压缩表述。","origin":"逐题标记","originalId":"s-957b60d95d82b5cf"}],"stem":"有关部门正在征集知识产权服务优秀案例，计划编印《知识产权服务案例汇编》。假如L市知识产权信息服务中心\n的相关实践入选为优秀案例，请你根据“给定资料4”，撰写一篇案例摘要。（15分）\n要求：\n（1）紧扣资料，内容全面，突出做法和意义；\n（2）表述准确，条理清晰；\n（3）不超过300字。","options":[],"answer":"","analysis":"参考答案一：\n                   关于L市知识产权信息服务中心案例摘要\n  该中心成立于2017年，持续面向社会开展知识产权服务工作，帮助一批品牌实现快速发展，典型案例有：\n  案例一——“川兴米粉”：指导其成为国家地理标志产品，带动品牌和行业发展；引导出台联盟及地方标准，提升\n产品质量，实现标准化、规范化的高质量发展。\n  案例二——“丰禾庄园”：协助企业分析研判发展问题，促成其与高端科研团队签署合作协议，解决生产中的关键\n问题，协调引进先进种植技术，方便采收、有效增产。\n  案例三——“伊山山珍”：定制品牌商标注册方案，开展宣讲培训，指导制定商标管理办法，提升信誉，联合多部\n门创新模式，推广主导产业，提升拳头产品市场认可度。\n  参考答案说明：（1）格式方面，本参考答案写到了“标题+正文”。（2）正文部分，一方面从内容上来看，围\n绕“L市知识产权信息服务中心的相关实践”这一主题，本参考答案的开头先写到了L市知识产权信息服务中心的背景信\n息；主体部分写到了“川兴米粉”“丰禾庄园”“伊山山珍”三个案例。另一方面，形式上，本参考答案做到了分段、分条\n撰写，整体上条理较为清晰。\n\n\n\n\n参考答案二：\n  案例摘要：L市知识产权信息服务中心成立于2017年，持续面向社会开展知识产权服务工作，帮助一批品牌实\n现快速发展。案例1“川兴米粉”：指导其成为国家地理标志产品，带动品牌和行业发展；引导出台联盟及地方标准，\n提升产品质量，实现标准化、规范化的高质量发展。案例2“丰禾庄园”：协助企业分析研判发展问题，促成其与高端\n科研团队签署合作协议，解决生产中的关键问题，协调引进先进种植技术，方便采收、有效增产。案例3“伊山山\n珍”：定制品牌商标注册方案，开展宣讲培训，指导制定商标管理办法，提升信誉，联合多部门创新模式，推广主导\n产业，提升拳头产品市场认可度。","figs":[],"state":"已标记","notes":[],"domains":["公共管理","经济"],"nature":"综合题","current":false}},"materialFiles":{"dd9e2108e0e953e8":"e962e9013bf4c2912216817b","7c24d384bc901351":"0c56d71553ad2c0d1ac5b248"},"terms":{"k-aafae58dc3dcc99d":{"id":"k-aafae58dc3dcc99d","mode":"k","type":"观点与论证","title":"地理标志保护与地方品牌","qs":[],"count":2},"k-da7b6ec6c3500908":{"id":"k-da7b6ec6c3500908","mode":"k","type":"事实与事件","title":"川兴米粉联盟标准与地方标准","qs":[],"count":1},"k-d46e483cd5c929cb":{"id":"k-d46e483cd5c929cb","mode":"k","type":"事实与事件","title":"丰禾庄园科研对接与技术引进","qs":[],"count":1},"k-4859f93707a81f3e":{"id":"k-4859f93707a81f3e","mode":"k","type":"事实与事件","title":"“伊山山珍”商标注册与使用管理","qs":[],"count":1},"k-58f1053a07e73a56":{"id":"k-58f1053a07e73a56","mode":"k","type":"事实与事件","title":"“伊山山珍”地理标志商标推广模式","qs":[],"count":1},"s-5cd530a611f08110":{"id":"s-5cd530a611f08110","mode":"s","type":"应用文写作","title":"编写案例摘要","qs":[],"count":2},"k-503f5332aa5742af":{"id":"k-503f5332aa5742af","mode":"k","type":"事实与事件","title":"川兴米粉的联盟标准与地方标准","qs":[],"count":1},"k-81247a9d1eef6b5e":{"id":"k-81247a9d1eef6b5e","mode":"k","type":"事实与事件","title":"丰禾庄园的产学合作与高垄种植","qs":[],"count":1},"k-c7b7c1663252e3e1":{"id":"k-c7b7c1663252e3e1","mode":"k","type":"事实与事件","title":"伊山山珍的商标注册与使用管理","qs":[],"count":1},"k-1ba04b82345af203":{"id":"k-1ba04b82345af203","mode":"k","type":"事实与事件","title":"伊山山珍的产业推广模式","qs":[],"count":1}},"questions":{}},"firstMaterials":[{"key":"dd9e2108e0e953e8","value":["材料2","材料2\n  “随着我国创新型国家建设和知识产权战略实施的不断推进，政府知识产权工作的着力点，已从知识产权制度的\n构建转变成为推动市场主体对知识产权制度的有效运用。”知识产权领域一位资深专家表示，“在我国知识产权制度从\n建立到不断完善的过程中，这将是我国知识产权事业发展的新方向。”\n  “在市知识产权信息服务中心的助力下，‘川兴米粉’获得地理标志保护，带动了整个企业品牌乃至行业的发展。我\n们通过不断完善特色加工工艺、加强历史文化传承等，持续推动‘川兴米粉’高质量发展。”L市镇办企业川兴米粉有限\n公司冯经理说。\n\n  L市知识产权信息服务中心成立于2017年10月，主要职能是面向社会开展知识产权法律法规宣传、专利技术展示\n宣传和推介转化，提供专利情报与商标信息、专利信息传播与利用、知识产权司法鉴定与知识产权培训等一系列服\n务工作。2018年，L市知识产权信息服务中心派专项组进驻各乡镇。在中心指导下，“川兴米粉”正式成为国家地理标\n志产品。2022年，在L市知识产权信息服务中心的引导下，“川兴米粉”联盟标准及地方标准先后出台。统一的标准是\n提升产品质量的保证，一路走来，“川兴米粉”在标准化和规范化道路上渐行渐稳，走上了高质量发展的“快车道”。\n  三月江南，草莓上市。在L市各大中高端超市的水果货架上，随处可见“丰禾庄园”的精品草莓。“丰禾庄园”是一家\n集草莓育种、种植与销售于一体的创新型企业。该企业吴经理介绍，企业赢得市场青睐的秘诀之一在于，L市知识产\n权信息服务中心协助企业分析研判发展“痛点”，精准对接高端科研团队，为产品的提档升级注入了科技基因。\n  通过知识产权信息服务中心的对接，L市农业学院方教授团队与“丰禾庄园”就草莓生产等方面展开合作。2021年\n底，三方围绕草莓育苗基质配制、有机肥研发利用、知识产权信息服务等需求，共同签署了“丰禾庄园与L市农业学院\n合作框架协议”。很快，方教授带领团队帮助企业解决了草莓生产中的一个个关键问题。\n  传统的地栽草莓垄高一般在20-30厘米，工人必须弯下腰来采摘，费时费力。为了改变这一现状，在L市知识产\n权信息服务中心的协调下，企业尝试引进高垄种植技术，不仅让草莓采收轻松省力，而且还利用其采光好、透气性\n强的优点，有效促进了草莓增产。\n  香田蓝莓花开、浮山春茶开采……良好的生态环境，孕育出千姿百态的“伊山山珍”。以前，这些产品虽好，但其\n经营户处于小、散、弱的状态，销售渠道也不通畅。\n  乡村振兴，产业兴旺是基础。为此，L市知识产权信息服务中心为“伊山山珍”品牌商标注册量身定制工作方案，\n确定注册商标样式，进行品牌知识产权保护布局、品牌图文版权登记等。针对山珍品种繁多问题，知识产权信息服\n务中心安排信息员就相关产品类别在国家知识产权局商标数据库对48个类别进行近200次检索，整理出商品商标申请\n清单和服务商标申请清单，指导相关企业将60余种产品分期分批开展商标注册申请。\n  “没有自己的品牌，好山珍卖不出好价钱。今年我们取得了‘伊山山珍’的商标使用权，对于销售信心倍增。”伊山\n村一位种植大户说。\n  “多年来，村里人专注于山珍的培育，却忽略了知识产权的保护，时有冒牌货流入市场，损害了本地山珍的信\n誉。”伊山农村联合社郑社长感慨，“知识产权信息服务中心给我们做了商标法宣讲，对商标持有人进行培训，并指导\n我们制定了《“伊山山珍”商标标识使用管理办法》。现在我们得到商标的授权，消费者对我们的信任度高了，销量自\n然上去了。”\n  L市知识产权信息服务中心还联合多个部门合力推动“企业+地理标志商标+标准化+农户”模式，重点推广当地主\n导产业，成功打造了以蓝莓、竹荪、两茶一药等为重点的“伊山山珍”拳头产品，许多产品备受顾客青睐和市场欢迎。",["ac29447768aa30db2247.pdf",1]],"label":"国考 2023 地市级 申论|材料2"}],"node":{"id":"s-5cd530a611f08110","mode":"s","title":"编写案例摘要","type":"应用文写作","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":["按案例归并并配对关键做法与成效","按案例提取并配对做法与成效"],"qs":["国考 2023 地市级 申论#2","国考 2023 行政执法 申论#4"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"subject":"申论","publishedSets":[{"name":"编写案例摘要","ids":["国考 2023 地市级 申论#2","国考 2023 行政执法 申论#4"],"units":[["国考 2023 地市级 申论#2"],["国考 2023 行政执法 申论#4"]]}]}};
